// Текст картки. Водій читає це з телефона одразу після поїздки.
// Якщо точки немає серед geofence, у полі лежать голі координати — віддаємо
// посилання на карту, бо самі цифри водієві нічого не кажуть.
const COORD = /^\s*(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)\s*$/;

function place(value) {
  const m = COORD.exec(String(value || ''));
  if (!m) return value;
  const [, lat, lon] = m;
  return `<a href="https://maps.google.com/?q=${lat},${lon}">📍 точка на карті</a>`;
}

return $input.all().map(i => {
  const t = i.json;
  const km = Number(t.distance_km).toFixed(1);
  const lines = [
    `🚐 <b>${t.start_local} → ${t.end_local}</b> · ${km} км`,
    `${place(t.origin_address)} → ${place(t.destination_address)}`
  ];
  if (t.review_reason) lines.push(`⚠️ ${t.review_reason}`);
  // Головне у картці — сказати, чого саме бракує і якою дією це закрити.
  lines.push(t.need === 'purpose'
    ? '↩️ <i>Тип уже стоїть, бракує мети. Відповідь на це повідомлення = мета поїздки.</i>'
    : '👇 <i>Обери тип поїздки кнопкою нижче.</i>');
  return { json: { ...t, card_text: lines.join('\n') } };
});
